function isPalindrome(s) {
  const letters = []
  for (const ch of s.toLowerCase()) {
    if (ch >= 'a' && ch <= 'z') letters.push(ch)
  }
  let left = 0
  let right = letters.length - 1
  while (left < right) {
    if (letters[left] !== letters[right]) return false
    left++
    right--
  }
  return true
}

