function isAnagram(a, b) {
  if (a.length !== b.length) return false
  const counts = new Map()
  for (const ch of a) counts.set(ch, (counts.get(ch) || 0) + 1)
  for (const ch of b) {
    const left = (counts.get(ch) || 0) - 1
    if (left < 0) return false
    counts.set(ch, left)
  }
  return true
}

